mkdir -p /tmp/corvane_claimschema_pkg && cd /tmp/corvane_claimschema_pkg && cat > setup.py << 'EOF'
from setuptools import setup
setup(
    name='corvane-claimschema',
    version='0.1.0',
    py_modules=['corvane_claimschema'],
)
EOF
cat > corvane_claimschema.py << 'PYEOF'
class SettlementSchema:
    _fields = ["claim_id", "amount", "status", "date"]

    def __init__(self, fields):
        self.fields = fields

    @classmethod
    def current(cls):
        return cls(cls._fields)
PYEOF
pip install . 2>&1

